service.method:

INSERT INTO SBUPR
	(
		  HOUSE_CODE
		, BIZ_CODE
		, BIZ_CATEGORY
		, BIZ_TYPE
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, CHANGE_DATE
		, CHANGE_TIME
		, CHANGE_USER_ID
		, DEL_FLAG
		, SELLER_NAME_LOC
		, IRS_NO
		, ZIP_CODE
		, ADDRESS_LOC
		, PHONE_NO
		, EMAIL
		, CEO_NAME_LOC
		, FOUNDATION_DATE
		, IF_FLAG
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${session.COMPANY_CODE}				
		, 'C'
		, 'S'
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, 'N'
		, ${SELLER_NAME_LOC}
		, ${IRS_NO}
		, ${ZIP_CODE}
		, ${ADDRESS_LOC}
		, ${PHONE_NO}
		, ${EMAIL}				
		, ${CEO_NAME_LOC}
		, ${FOUNDATION_DATE}
		, ${IF_FLAG}
	)


SELECT
		  USER_ID
		, MENU_PROFILE_CODE
		, USER_TYPE
FROM
	SUSMT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${COMPANY_CODE}	
	AND USER_ID 		= ${USER_ID}


UPDATE SUSMT
   SET
		  CHANGE_DATE    	= ${current.DATE}
		, CHANGE_TIME    	= ${current.TIME}
		, CHANGE_USER_ID  	= ${session.ID}				  
		, USER_NAME_LOC	 	= ${USER_NAME_LOC}
		, USER_NAME_ENG	 	= ${USER_NAME_ENG}
		, DEPT		      	= ${DEPT}
		, POSITION		  	= ${POSITION}
		, EMAIL  		    = ${EMAIL}
		, PHONE           	= ${PHONE}
		, employee_no       = ${EMPLOYEE_NO}
		, DEL_FLAG        	= ${DEL_FLAG}
		, LANGUAGE			= 'KO'
		, USER_TYPE			= #DB_OWNER#nvl($S{USER_TYPE}, USER_TYPE)
WHERE
	  HOUSE_CODE        	= ${session.HOUSE_CODE}
  AND COMPANY_CODE 			= ${COMPANY_CODE}
  AND USER_ID           	= ${USER_ID}


UPDATE SBUPI
SET  
	 USER_NAME			= ${USER_NAME_LOC}
	,EMAIL				= ${EMAIL}
	,PHONE_NO			= ${PHONE_NO}
	,CHANGE_DATE		= ${current.DATE}
	,CHANGE_TIME		= ${current.TIME}
	,CHANGE_USER_ID		= ${session.ID}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND BIZ_CODE = ${COMPANY_CODE}
	AND USER_ID = ${USER_ID}


INSERT INTO SUSMT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, USER_ID 
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID
		, PLANT_CODE
		, USER_NAME_LOC
		, USER_NAME_ENG
		, PASSWORD
		, DEPT
		, POSITION
		, EMAIL		
		, COUNTRY
		, SIGN_STATUS
		, WORK_TYPE
		, MENU_PROFILE_CODE
		, USER_TYPE
		, PASS_CHECK_CNT
		, PW_RESET_FLAG
		, DEL_FLAG
		, DATE_FORMAT
		, PHONE
		, LANGUAGE
		, EMPLOYEE_NO
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${COMPANY_CODE}
		, ${USER_ID}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}
		, ${COMPANY_CODE}
		, ${USER_NAME_LOC}
		, ${USER_NAME_ENG}
		, ${PASSWORD}
		, ${DEPT}
		, ${POSITION}
		, ${EMAIL}				
		, 'KR'
		, 'A'
		, 'G'
		, ${MENU_PROFILE_CODE}
		, 'A'
		, '0'
		, 'N'
		, ${DEL_FLAG}
		, '%Y/%m/%d'
		, ${PHONE}
		, 'KO'
		, ${EMPLOYEE_NO}
	)
